P1_shortcut.text:
has_non_shift_modifier = any(modifier != "shift" for modifier in modifiers)
character: str | None = None
if not has_non_shift_modifier:
    if text is not None:
        character = text
    elif "shift" in modifiers and shifted_code is not None:
        try:
            shifted_character = chr(shifted_code)
        except (ValueError, OverflowError):
            shifted_character = ""
        if shifted_character.isprintable():
            character = shifted_character
    elif key_character is not None and key_character.isprintable():
        character = key_character

# Shift-only printable keys remain printable events. Other modified
# keys use a stable shortcut name based on the unshifted key.
if modifiers == ("shift",) and character is not None:
    key = _character_to_key(character)
else:
    key = _key_with_modifiers(base_key, modifiers)

P1_non_u_branch.text:
if (match := _re_extended_key.fullmatch(sequence)) is not None:
    number, modifier_parameter, end = match.groups()
    number = number or "1"
    if not (key := FUNCTIONAL_KEYS.get(f"{number}{end}", "")):
        try:
            key = _character_to_key(chr(int(number)))
        except (ValueError, OverflowError):
            return
    modifiers = _decode_modifiers(modifier_parameter)
    base_key = key.lower()
    yield events.Key(
        _key_with_modifiers(base_key, modifiers),
        sequence if len(sequence) == 1 else None,
        modifiers=modifiers,
        base_key=base_key,
    )
